/*
 * stubs.c - WEAK placeholder implementations so the project builds from day one.
 * When a teammate adds the real function in their own file (access.c, room.c,
 * storage.c, cli.c), the linker automatically prefers theirs. Do not edit this file
 * to add real logic; delete a stub only when everyone's real code is merged.
 */
#include "esp_log.h"
#include "shared.h"

static const char *TAG = "stub";

static void idle_forever(void)
{
    for (;;) vTaskDelay(pdMS_TO_TICKS(1000));
}

__attribute__((weak)) void entrance_task(void *arg) { (void)arg; idle_forever(); }
__attribute__((weak)) void room_task(void *arg)     { (void)arg; idle_forever(); }
__attribute__((weak)) void cli_task(void *arg)      { (void)arg; idle_forever(); }

/* Default storage: just print every event to the console so everyone can see their events. */
__attribute__((weak)) void storage_task(void *arg)
{
    (void)arg;
    log_event_t e;
    for (;;) {
        if (xQueueReceive(g_log_queue, &e, portMAX_DELAY) == pdTRUE) {
            ESP_LOGI(TAG, "[%lu] type=%d src=%d uid=%s note=%s",
                     (unsigned long)e.ts, (int)e.type, e.source, e.uid, e.note);
        }
    }
}

/* Default reader: takes simulated scans pushed by the serial menu ("scan entry <uid>").
 * Daniel may replace this with a real RC522 driver if Wokwi supports one. */
__attribute__((weak)) bool rfid_poll(door_id_t door, char uid_out[UID_LEN])
{
    scan_msg_t m;
    if ((int)door < 0 || (int)door > 1) return false;
    if (xQueueReceive(g_scan_queue[door], &m, 0) == pdTRUE) {
        strncpy(uid_out, m.uid, UID_LEN - 1);
        uid_out[UID_LEN - 1] = '\0';
        return true;
    }
    return false;
}

__attribute__((weak)) void report_print_summary(void) { ESP_LOGI(TAG, "report_print_summary not implemented yet"); }
__attribute__((weak)) void report_print_inside(void)  { ESP_LOGI(TAG, "report_print_inside not implemented yet"); }
